  .reproduction-same {
    border-style: double;
    border-width: 3px;
  }

  .pairing-values {
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem 1rem;
  }

  .histogram-scroll,
  .table-scroll {
    --diagram-scroll-inline-size: 100%;
  }

  .histogram-table {
    inline-size: 100%;
    min-inline-size: 48rem;
    table-layout: fixed;
  }

  .histogram-table th:first-child {
    inline-size: 10rem;
  }

  .histogram-table :is(th, td):not(:first-child) {
    text-align: center;
  }

  .histogram-table tbody th {
    vertical-align: middle;
  }

  .histogram-range {
    display: grid;
    justify-items: center;
  }

  .bin-evidence {
